"""Test 19: the analysis of one date (t19-rule.md sections 4 to 7). Fixed before the date's data.

Per qubit read: P(1|0) from S0 and P(0|1) from S1, the copies pooled (4,000 shots each); e = (P(1|0) + P(0|1)) / 2;
se = 1/2 sqrt(P(1|0)(1 - P(1|0)) / 4,000 + P(0|1)(1 - P(0|1)) / 4,000), floored at 0.0005; p the published
readout_error at the stamp in force at submission; d = p - e; the class and the date's word by t19_classes.py (the same
module the desk check ran). If a new stamp appeared before the job finished, the word is also computed against it and
reported beside. From the second date on, the series word over every date read, with the count and the days spanned.

Reported beside (section 7): the chip at a glance; the per-qubit table; 15 October under this rule (Kickoff 62's
survey-62.json, classed the same way, se at its 4,000 shots per state); the same qubits or different ones (overlap of
PUBLISHED ABOVE with each earlier date and with 15 October; the Spearman rank correlation of d between each pair); the
table across stamps (48 hours before the job: qubits whose published readout error changed by more than 0.01 between
consecutive stamps); qubit 143; the stamps, the estimate and the decision (no allowance figure).

Outcome bits: clbit i holds qubits_read[i] (Qiskit key order, clbit 0 rightmost), read with Kickoff 62's bit_matrix.
Usage: analyse_t19.py N OUT_DIR   (OUT_DIR the date's hand-back folder; earlier dates read from its parent)"""
from __future__ import annotations

import hashlib
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(TRACE / "t19-fez-readout-dates" / "scripts"))
from t19_classes import measured, qubit_class, date_word, series_word, SHOTS  # noqa: E402

K62 = HERE.parent / "hardware-62"
CLASSES = ["PUBLISHED ABOVE", "MEASURED ABOVE", "AGREE", "BETWEEN"]


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def ts(s):
    return datetime.fromisoformat(str(s).replace("Z", "+00:00")).astimezone(timezone.utc)


def bit_matrix(keys, n):
    """Kickoff 62's analyse_62.bit_matrix, copied unchanged: column i = clbit i."""
    keys = [k.replace(" ", "") for k in keys]
    if not keys:
        return np.zeros((0, n), dtype=np.int64)
    a = np.frombuffer("".join(keys).encode(), dtype=np.uint8).reshape(len(keys), n).astype(np.int64) - 48
    return a[:, ::-1]


def pooled(labels, counts):
    qs = labels[0]["qubits_read"]
    n = len(qs)
    ones = {"S0": np.zeros(n, dtype=np.int64), "S1": np.zeros(n, dtype=np.int64)}
    tot = {"S0": 0, "S1": 0}
    by_copy = {"S0": {}, "S1": {}}
    for lab, cts in zip(labels, counts):
        keys = list(cts)
        B = bit_matrix(keys, n)
        v = np.array([cts[k] for k in keys], dtype=np.int64)
        o = v @ B
        ones[lab["circuit"]] += o
        tot[lab["circuit"]] += int(v.sum())
        by_copy[lab["circuit"]][lab["copy"]] = (o, int(v.sum()))
    p10 = ones["S0"] / tot["S0"]
    p01 = 1 - ones["S1"] / tot["S1"]
    return qs, p10, p01, tot, by_copy


def classify(qs, p10, p01, pub, shots):
    rows = {}
    for i, q in enumerate(qs):
        e, se = measured(float(p10[i]), float(p01[i]), shots)
        p = pub[str(q)]["readout_error"]
        d = p - e
        rows[str(q)] = {"P1_given_0": float(p10[i]), "P0_given_1": float(p01[i]), "e": e, "se": se, "p": p, "d": d, "class": qubit_class(d, se)}
    cls = [r["class"] for r in rows.values()]
    counts = {c: cls.count(c) for c in CLASSES}
    return rows, counts, date_word(cls)


def glance(rows):
    e = np.array([r["e"] for r in rows.values()])
    p = np.array([r["p"] for r in rows.values()])
    return {"median_e": float(np.median(e)), "median_p": float(np.median(p)),
            "n_above_0.03_measured": int((e > 0.03).sum()), "n_above_0.03_published": int((p > 0.03).sum())}


def ranks(x):
    x = np.asarray(x, dtype=float)
    order = np.argsort(x, kind="mergesort")
    r = np.empty(len(x))
    r[order] = np.arange(len(x), dtype=float)
    for v in np.unique(x):           # average ranks for ties
        m = x == v
        if m.sum() > 1:
            r[m] = r[m].mean()
    return r


def spearman(a, b):
    ra, rb = ranks(a), ranks(b)
    return float(np.corrcoef(ra, rb)[0, 1])


def pub_of(snap, qs):
    out = {}
    for q in qs:
        v = {x["name"]: x["value"] for x in snap["qubits"][int(q)]}
        out[str(q)] = {k: (None if v.get(k) is None else float(v[k])) for k in ("readout_error", "prob_meas1_prep0", "prob_meas0_prep1")}
    return out


def oct15():
    sv = json.loads((K62 / "survey-62.json").read_text())
    qs = sorted(sv["qubits"], key=int)
    rows = {}
    for q in qs:
        v = sv["qubits"][q]
        e, se = measured(v["P1_given_0"], v["P0_given_1"], 4000)
        p = v["published"]["readout_error"]
        rows[q] = {"P1_given_0": v["P1_given_0"], "P0_given_1": v["P0_given_1"], "e": e, "se": se, "p": p, "d": p - e, "class": qubit_class(p - e, se)}
    cls = [r["class"] for r in rows.values()]
    return {"source": "hardware-62/survey-62.json (Kickoff 62's published survey file)", "source_sha256": sha(K62 / "survey-62.json"),
            "stamp_in_force": sv["stamp_at_submission_utc"], "n": len(rows), "counts": {c: cls.count(c) for c in CLASSES},
            "word_under_this_rule": date_word(cls), "glance": glance(rows),
            "note": "beside the series only; 15 October is not a date of this series; nothing in Kickoff 62's record changes"}, rows


def table_across_stamps(N, job_sub_utc):
    """48 hours before the job: per consecutive pair of stamps, qubits whose published readout_error changed by more than 0.01."""
    snaps = sorted((HERE / "history-t19" / "snapshots").glob("snapshot-*.json"))
    w = json.loads((HERE / "history-t19" / "walk-01.json").read_text())
    start = ts(w["start_utc"])
    items = []
    for p in snaps:
        d = json.loads(p.read_text())
        st = ts(d["last_update_date"])
        items.append((st, p.name, d))
    items.sort(key=lambda x: x[0])
    out, prev = [], None
    for st, name, d in items:
        re_ = {}
        for qi, ql in enumerate(d["qubits"]):
            v = {x["name"]: x["value"] for x in ql}
            re_[qi] = v.get("readout_error")
        if prev is not None and st >= start:
            ch = [q for q in re_ if re_[q] is not None and prev[1].get(q) is not None and abs(re_[q] - prev[1][q]) > 0.01]
            out.append({"from_stamp_utc": prev[0].strftime("%Y-%m-%dT%H:%M:%SZ"), "to_stamp_utc": st.strftime("%Y-%m-%dT%H:%M:%SZ"),
                        "n_qubits_readout_error_changed_by_more_than_0.01": len(ch)})
        prev = (st, re_)
    return {"window_start_utc": w["start_utc"], "walk_end_utc": w.get("end_utc"), "pairs": out}


def main():
    N = int(sys.argv[1])
    OUT = Path(sys.argv[2])
    OUT.mkdir(parents=True, exist_ok=True)
    sub = json.loads((HERE / f"submit-t19-d{N}.json").read_text())
    res = json.loads((HERE / f"results-t19-d{N}-counts.json").read_text())
    stamps = json.loads((HERE / f"stamps-t19-d{N}.json").read_text())
    dec = json.loads((HERE / f"decision-t19-d{N}.json").read_text())
    if not res.get("counts"):
        print("no counts: the date reports no word")
        return
    labels, counts = sub["labels"], res["counts"]
    qs, p10, p01, tot, by_copy = pooled(labels, counts)
    assert tot == {"S0": SHOTS, "S1": SHOTS}, tot
    # the published tables in force during the job
    sub_snap_name = sub["stamp_row"]["snapshot"]
    snap_sub = json.loads((HERE / "stamps-t19" / sub_snap_name).read_text())
    pub_sub = pub_of(snap_sub, qs)
    tsd = res.get("timestamps") or {}
    finished = ts(tsd["finished"]) if tsd.get("finished") else None
    later = []
    seen = {sub_snap_name}
    for r in stamps:
        if r["snapshot"] in seen:
            continue
        seen.add(r["snapshot"])
        st = ts(r["stamp_utc"])
        if st > ts(sub["stamp_row"]["stamp_utc"]) and (finished is None or st <= finished):
            later.append(r["snapshot"])
    tables = {"at_submission": {"stamp_utc": sub["stamp_row"]["stamp_utc"], "snapshot": sub_snap_name, "qubits": pub_sub}}
    beside_words = {}
    for name in later:
        sn = json.loads((HERE / "stamps-t19" / name).read_text())
        pb = pub_of(sn, qs)
        tables[f"new_before_finish:{name}"] = {"stamp_utc": ts(sn["last_update_date"]).strftime("%Y-%m-%dT%H:%M:%SZ"), "snapshot": name, "qubits": pb}
        _, c2, w2 = classify(qs, p10, p01, pb, SHOTS)
        beside_words[name] = {"counts": c2, "word": w2}
    rows, cnt, word = classify(qs, p10, p01, pub_sub, SHOTS)
    for i, q in enumerate(qs):
        rows[str(q)]["P1_given_0_by_copy"] = [float(by_copy["S0"][c][0][i] / by_copy["S0"][c][1]) for c in (1, 2)]
        rows[str(q)]["P0_given_1_by_copy"] = [float(1 - by_copy["S1"][c][0][i] / by_copy["S1"][c][1]) for c in (1, 2)]
    n = len(qs)
    # the series
    prior = []
    for k in range(1, N):
        cp = OUT.parent / f"d{k}" / f"classes-t19-d{k}.json"
        if not cp.exists():
            sys.exit(f"STOP: date {k}'s classes are not in the hand-back")
        prior.append(json.loads(cp.read_text()))
    this = {"date": N, "job_submitted_utc": sub["submitted_utc"], "word": word}
    series = [{"date": c["date"], "utc_date": c["utc_date"], "word": c["word"]} for c in prior] + [
        {"date": N, "utc_date": sub["submitted_utc"][:10], "word": word}]
    days = (ts(series[-1]["utc_date"] + "T00:00:00Z") - ts(series[0]["utc_date"] + "T00:00:00Z")).days
    ser = None
    if N >= 2:
        ser = {"dates": len(series), "days_spanned": days, "series_word": series_word([s["word"] for s in series]),
               "a_week_of_dates": len(series) >= 5 and days >= 6, "dates_read": series}
    o15, rows15 = oct15()
    pa_now = {q for q, r in rows.items() if r["class"] == "PUBLISHED ABOVE"}
    same = {"published_above_this_date": len(pa_now),
            "of_these_published_above_on_15_october": len(pa_now & {q for q, r in rows15.items() if r["class"] == "PUBLISHED ABOVE"})}
    rho = {}
    common15 = [q for q in rows if q in rows15]
    rho[f"d{N}_vs_15_october"] = {"n": len(common15), "spearman_d": spearman([rows[q]["d"] for q in common15], [rows15[q]["d"] for q in common15])}
    for c in prior:
        pr = c["qubits"]
        same[f"of_these_published_above_on_d{c['date']}"] = len(pa_now & {q for q, r in pr.items() if r["class"] == "PUBLISHED ABOVE"})
        common = [q for q in rows if q in pr]
        rho[f"d{N}_vs_d{c['date']}"] = {"n": len(common), "spearman_d": spearman([rows[q]["d"] for q in common], [pr[q]["d"] for q in common])}
    for i, a in enumerate(prior):
        for b in prior[i + 1:]:
            common = [q for q in a["qubits"] if q in b["qubits"]]
            rho[f"d{a['date']}_vs_d{b['date']}"] = {"n": len(common), "spearman_d": spearman([a["qubits"][q]["d"] for q in common], [b["qubits"][q]["d"] for q in common])}
    q143 = {"date": rows.get("143") and {k: rows["143"][k] for k in ("e", "p", "d", "class")},
            "15_october": {k: rows15["143"][k] for k in ("e", "p", "d", "class")}}
    classes = {"rule": "t19-rule.md sections 4 and 5", "date": N, "utc_date": sub["submitted_utc"][:10], "job_id": sub["job_id"],
               "stamp_in_force_at_submission": sub["stamp_row"]["stamp_utc"], "n_read": n,
               "not_operational_listed_not_read": sub["not_operational_listed_not_read"],
               "thresholds": {"quarter_of_n": n / 4, "one_in_twenty_of_n": n / 20, "measured_above_max_for_gap": cnt["PUBLISHED ABOVE"] / 10},
               "counts": cnt, "word": word, "words_against_other_tables_in_force": beside_words, "qubits": rows}
    (OUT / f"classes-t19-d{N}.json").write_text(json.dumps(classes, indent=1))
    (OUT / f"published-t19-d{N}.json").write_text(json.dumps({"date": N, "tables": tables}, indent=1))
    (OUT / f"survey-t19-d{N}.json").write_text(json.dumps({k: res[k] for k in res if k not in ("meta", "usage")} | {"labels": labels, "meta": res.get("meta")}, indent=1, default=str))
    summ = {"date": N, "counts": cnt, "word": word, "n_read": n, "beside_words": beside_words, "series": ser,
            "glance": glance(rows), "oct15": o15, "same_or_different": same, "rank_correlation_d": rho,
            "table_across_stamps": table_across_stamps(N, sub["submitted_utc"]), "qubit_143": q143,
            "stamps": [{k: r[k] for k in ("utc", "kind", "stamp_utc", "new_stamp_since_last_row", "job_status") if k in r} | ({"changed": r["changed"]} if "changed" in r else {}) for r in stamps],
            "estimate": dec["estimate"], "decision": dec["decision"], "job_timestamps": res.get("timestamps"),
            "usage_seconds_charged": (res.get("usage") or {}).get("quantum_seconds")}
    (HERE / f"summary-t19-d{N}.json").write_text(json.dumps(summ, indent=1, default=str))
    print(json.dumps({k: summ[k] for k in ("counts", "word", "n_read", "beside_words", "series", "glance", "same_or_different", "qubit_143")}, indent=1, default=str))
    print("15 October:", o15["counts"], o15["word_under_this_rule"])


if __name__ == "__main__":
    main()

