"""Test 19: classes (section 4) and words (sections 5 and 6), exactly as t19-rule.md states them."""
import math

SHOTS = 4000
SE_FLOOR = 0.0005


def measured(p10, p01, shots=SHOTS):
    e = (p10 + p01) / 2
    se = 0.5 * math.sqrt(p10 * (1 - p10) / shots + p01 * (1 - p01) / shots)
    return e, max(se, SE_FLOOR)


def qubit_class(d, se):
    if d > 0.05 and d > 3 * se:
        return "PUBLISHED ABOVE"
    if -d > 0.01 and -d > 3 * se:
        return "MEASURED ABOVE"
    if abs(d) <= max(0.01, 3 * se):
        return "AGREE"
    return "BETWEEN"


def date_word(classes):
    n = len(classes)
    pa = sum(c == "PUBLISHED ABOVE" for c in classes)
    ma = sum(c == "MEASURED ABOVE" for c in classes)
    if pa >= n / 4 and ma <= pa / 10:
        return "ONE-SIDED GAP"
    if pa < n / 20 and ma < n / 20:
        return "TABLE DESCRIBES THE DEVICE"
    return "MIXED"


def series_word(words):
    gaps = [w == "ONE-SIDED GAP" for w in words]
    if all(gaps):
        return "GAP ON EVERY DATE"
    if not any(gaps):
        return "GAP ON NO DATE"
    return "GAP ON SOME DATES"

